package main

import (
	"fmt"
	"strings"
)

// field is one of the five cron fields: a bitmask of the values it admits.
// restricted records whether the field was written as something other than "*",
// which the day-of-month / day-of-week union rule depends on.
type field struct {
	mask       uint64
	restricted bool
}

func (f field) has(v int) bool { return v >= 0 && v < 64 && f.mask&(1<<uint(v)) != 0 }

// Schedule is a parsed cron expression.
type Schedule struct {
	minute, hour, dom, month, dow field
	expr                          string
}

type spec struct {
	name     string
	min, max int
	names    []string // optional, index 0 == min
}

var specs = []spec{
	{name: "minute", min: 0, max: 59},
	{name: "hour", min: 0, max: 23},
	{name: "day-of-month", min: 1, max: 31},
	{name: "month", min: 1, max: 12},
	{name: "day-of-week", min: 0, max: 6},
}

// ParseError names the field that was malformed, so callers never have to guess.
type ParseError struct {
	Field string
	Term  string
	Msg   string
}

func (e *ParseError) Error() string {
	if e.Term == "" {
		return fmt.Sprintf("%s: %s", e.Field, e.Msg)
	}
	return fmt.Sprintf("%s: %q: %s", e.Field, e.Term, e.Msg)
}

// Parse turns a five-field cron expression into a Schedule.
func Parse(expr string) (*Schedule, error) {
	fields := strings.Fields(expr)
	if len(fields) != 5 {
		return nil, &ParseError{Field: "expression", Msg: fmt.Sprintf("expected 5 fields, got %d", len(fields))}
	}
	s := &Schedule{expr: strings.Join(fields, " ")}
	out := []*field{&s.minute, &s.hour, &s.dom, &s.month, &s.dow}
	for i, raw := range fields {
		f, err := parseField(raw, specs[i])
		if err != nil {
			return nil, err
		}
		*out[i] = f
	}
	return s, nil
}

func parseField(raw string, sp spec) (field, error) {
	if raw == "*" {
		return field{mask: maskRange(sp.min, sp.max, 1)}, nil
	}
	return field{}, &ParseError{Field: sp.name, Term: raw, Msg: "unrecognised"}
}

func maskRange(lo, hi, step int) uint64 {
	var m uint64
	for v := lo; v <= hi; v += step {
		m |= 1 << uint(v)
	}
	return m
}
