func TestParseRestricted(t *testing.T) {
	s, _ := Parse("0 0 1 * 1")
	if !s.dom.restricted || !s.dow.restricted {
		t.Fatal("explicit dom/dow must be restricted")
	}
	s, _ = Parse("0 0 * * *")
	if s.dom.restricted || s.dow.restricted {
		t.Fatal("* dom/dow must not be restricted")
	}
	s, _ = Parse("0 0 */1 * *")
	if !s.dom.restricted {
		t.Fatal("*/1 is a step, not a bare star: restricted")
	}
