func TestParseMacros(t *testing.T) {
	cases := map[string]string{
		"@hourly":  "0 * * * *",
		"@daily":   "0 0 * * *",
		"@weekly":  "0 0 * * 0",
		"@monthly": "0 0 1 * *",
		"@yearly":  "0 0 1 1 *",
	}
	for macro, want := range cases {
		got, err := Parse(macro)
		if err != nil {
			t.Fatalf("Parse(%q): %v", macro, err)
		}
		exp, err := Parse(want)
		if err != nil {
			t.Fatal(err)
		}
		if *got != *exp {
			t.Fatalf("%s: got %+v, want %+v", macro, got, exp)
		}
	}
}

