	cases := []struct{ expr, wantField string }{
		{"60 * * * *", "minute"},
		{"* 24 * * *", "hour"},
		{"* * 0 * *", "day-of-month"},
		{"* * 32 * *", "day-of-month"},
		{"* * * 13 * ", "month"},
		{"* * * FOO *", "month"},
		{"* * * * 8", "day-of-week"},
		{"* * * * MONDAY", "day-of-week"},
		{"*/0 * * * *", "minute"},
		{"5-1 * * * *", "minute"},
		{"a * * * *", "minute"},
		{"* * * *", "expression"},
