package main

import (
	"testing"
	"time"
)

func mustParse(t *testing.T, expr string) *Schedule {
	t.Helper()
	s, err := Parse(expr)
	if err != nil {
		t.Fatalf("Parse(%q): %v", expr, err)
	}
	return s
}

func mustLoad(t *testing.T, zone string) *time.Location {
	t.Helper()
	loc, err := time.LoadLocation(zone)
	if err != nil {
		t.Fatalf("LoadLocation(%q): %v", zone, err)
	}
	return loc
}

func at(t *testing.T, iso string, loc *time.Location) time.Time {
	t.Helper()
	ts, err := time.ParseInLocation("2006-01-02T15:04:05", iso, loc)
	if err != nil {
		t.Fatalf("bad time %q: %v", iso, err)
	}
	return ts
}

func TestNextBasic(t *testing.T) {
	cases := []struct {
		expr, from, want string
	}{
		{"* * * * *", "2024-01-01T00:00:00", "2024-01-01T00:01:00"},
		{"* * * * *", "2024-01-01T00:00:30", "2024-01-01T00:01:00"}, // sub-minute rounds up
		{"*/15 * * * *", "2024-01-01T00:00:00", "2024-01-01T00:15:00"},
		{"0 * * * *", "2024-01-01T00:30:00", "2024-01-01T01:00:00"},
		{"0 0 * * *", "2024-01-01T12:00:00", "2024-01-02T00:00:00"},
		{"59 23 31 12 *", "2024-01-01T00:00:00", "2024-12-31T23:59:00"},
		{"0 0 1 * *", "2024-01-31T00:00:00", "2024-02-01T00:00:00"},  // month rollover
		{"0 0 29 2 *", "2024-03-01T00:00:00", "2028-02-29T00:00:00"}, // leap years only
		{"0 12 * * MON", "2024-01-01T13:00:00", "2024-01-08T12:00:00"},
	}
	for _, c := range cases {
		s := mustParse(t, c.expr)
		got, err := s.Next(at(t, c.from, time.UTC))
		if err != nil {
			t.Fatalf("%s from %s: %v", c.expr, c.from, err)
		}
		if want := at(t, c.want, time.UTC); !got.Equal(want) {
			t.Errorf("%s from %s: got %s, want %s", c.expr, c.from, got, want)
		}
	}
}

// When both day-of-month and day-of-week are restricted, either one matching is enough.
func TestNextDayOfMonthOrDayOfWeek(t *testing.T) {
	// 2024-03: the 1st is a Friday, so Mondays are 4, 11, 18, 25.
	s := mustParse(t, "0 0 15 * MON")
	got, err := s.NextN(at(t, "2024-03-01T00:01:00", time.UTC), 4)
	if err != nil {
		t.Fatal(err)
	}
	want := []string{"2024-03-04T00:00:00", "2024-03-11T00:00:00", "2024-03-15T00:00:00", "2024-03-18T00:00:00"}
	for i, w := range want {
		if !got[i].Equal(at(t, w, time.UTC)) {
			t.Errorf("[%d] got %s, want %s", i, got[i], w)
		}
	}

	// Only day-of-month restricted: day-of-week must not narrow it.
	s = mustParse(t, "0 0 15 * *")
	one, _ := s.Next(at(t, "2024-03-01T00:00:00", time.UTC))
	if !one.Equal(at(t, "2024-03-15T00:00:00", time.UTC)) {
