	}
	// Only day-of-week restricted.
	s = mustParse(t, "0 0 * * MON")
	one, _ = s.Next(at(t, "2024-03-01T00:00:00", time.UTC))
	if !one.Equal(at(t, "2024-03-04T00:00:00", time.UTC)) {
		t.Errorf("dow-only: got %s", one)
	}
