func TestNextImpossibleDate(t *testing.T) {
	s := mustParse(t, "0 0 30 2 *")
	if _, err := s.Next(at(t, "2024-01-01T00:00:00", time.UTC)); err == nil {
		t.Fatal("expected an error for 30 February")
	}
}

func TestNextInZone(t *testing.T) {
	tokyo := mustLoad(t, "Asia/Tokyo")
	s := mustParse(t, "0 9 * * *")
	got, err := s.Next(at(t, "2024-01-01T00:00:00", tokyo))
	if err != nil {
		t.Fatal(err)
	}
	if !got.Equal(at(t, "2024-01-01T09:00:00", tokyo)) {
		t.Fatalf("got %s", got)
	}
	if got.Location() != tokyo {
		t.Fatalf("result should stay in the requested zone, got %s", got.Location())
	}
}

// Spring forward: 2024-03-10 in New York, 02:00 jumps to 03:00. A job scheduled
// inside the gap must still run, at the first wall-clock instant that exists.
func TestNextSpringForwardDoesNotSkip(t *testing.T) {
	ny := mustLoad(t, "America/New_York")
	s := mustParse(t, "30 2 * * *")
	got, err := s.Next(at(t, "2024-03-09T12:00:00", ny))
	if err != nil {
		t.Fatal(err)
	}
	want := at(t, "2024-03-10T03:00:00", ny) // the instant the clock jumps
	if !got.Equal(want) {
		t.Fatalf("got %s, want %s", got, want)
	}

	// Several scheduled times inside one gap collapse to a single occurrence.
	s = mustParse(t, "0,15,30,45 2 * * *")
	four, err := s.NextN(at(t, "2024-03-09T23:00:00", ny), 2)
	if err != nil {
		t.Fatal(err)
	}
	if !four[0].Equal(want) {
		t.Fatalf("first: got %s, want %s", four[0], want)
	}
	if four[1].Equal(four[0]) {
		t.Fatalf("gap produced a duplicate: %s", four[1])
	}
}

// Fall back: 2024-11-03 in New York, 01:00-01:59 happens twice. A job scheduled
// in that hour must run once, not twice.
func TestNextFallBackDoesNotDuplicate(t *testing.T) {
	ny := mustLoad(t, "America/New_York")
	s := mustParse(t, "30 1 * * *")
	got, err := s.NextN(at(t, "2024-11-02T12:00:00", ny), 2)
	if err != nil {
		t.Fatal(err)
	}
	if got[0].Day() != 3 || got[1].Day() != 4 {
		t.Fatalf("01:30 fired twice on the repeated hour: %s, %s", got[0], got[1])
	}
}

// Whatever the expression, occurrences advance strictly and never repeat a
// wall-clock time across a DST boundary in either direction.
func TestNextAcrossDSTIsStrictlyIncreasing(t *testing.T) {
	ny := mustLoad(t, "America/New_York")
	for _, expr := range []string{"* * * * *", "*/30 * * * *", "0 * * * *", "0 2 * * *"} {
		for _, from := range []string{"2024-03-09T23:00:00", "2024-11-02T23:00:00"} {
			s := mustParse(t, expr)
			got, err := s.NextN(at(t, from, ny), 100)
			if err != nil {
				t.Fatal(err)
			}
			seen := map[string]bool{}
			for i, g := range got {
				if i > 0 && !g.After(got[i-1]) {
					t.Fatalf("%s from %s: %s does not advance past %s", expr, from, g, got[i-1])
				}
				wall := g.Format("2006-01-02T15:04:05")
				if seen[wall] {
					t.Fatalf("%s from %s: wall clock %s repeated", expr, from, wall)
				}
				seen[wall] = true
			}
		}
	}
}

func TestMatch(t *testing.T) {
	cases := []struct {
		expr, ts string
		want     bool
	}{
		{"0 9 * * *", "2024-01-01T09:00:00", true},
		{"0 9 * * *", "2024-01-01T09:01:00", false},
		{"0 9 * * *", "2024-01-01T09:00:30", false}, // seconds must be zero
		{"*/15 * * * *", "2024-01-01T10:45:00", true},
		{"0 0 15 * MON", "2024-03-04T00:00:00", true}, // matched via day-of-week
		{"0 0 15 * MON", "2024-03-15T00:00:00", true}, // matched via day-of-month
		{"0 0 15 * MON", "2024-03-05T00:00:00", false},
		{"@daily", "2024-06-01T00:00:00", true},
	}
	for _, c := range cases {
		s := mustParse(t, c.expr)
		if got := s.Match(at(t, c.ts, time.UTC)); got != c.want {
			t.Errorf("Match(%q, %q) = %v, want %v", c.expr, c.ts, got, c.want)
		}
	}
}
