package main

import (
	"fmt"
	"time"
)

// maxYearsAhead bounds the search so an expression that can never fire —
// 30 February, say — reports that instead of looping forever. Eight years
// clears the widest real gap, 29 February either side of a skipped leap year.
const maxYearsAhead = 8

// Next returns the first time strictly after `after` that the schedule fires,
// in the location of `after`.
func (s *Schedule) Next(after time.Time) (time.Time, error) {
	ts, err := s.NextN(after, 1)
	if err != nil {
		return time.Time{}, err
	}
	return ts[0], nil
}

// NextN returns the next n firing times after `after`, in its location.
//
// The search walks wall-clock time, not elapsed time, and then maps each
// wall-clock slot onto a real instant. That is what keeps daylight saving
// honest: a slot inside a skipped hour maps to the instant the clock jumps
// rather than vanishing, and a slot inside a repeated hour is visited once,
// so it cannot fire twice. Slots that collapse onto the same instant, or onto
// one already returned, are dropped by the strictly-increasing check.
func (s *Schedule) NextN(after time.Time, n int) ([]time.Time, error) {
	loc := after.Location()
	// A naive UTC time used purely as a wall-clock carrier, so that calendar
	// arithmetic below is never itself perturbed by an offset change.
	wall := time.Date(after.Year(), after.Month(), after.Day(), after.Hour(), after.Minute(), 0, 0, time.UTC).Add(time.Minute)
	limit := wall.Year() + maxYearsAhead

	out := make([]time.Time, 0, n)
	prev := after
	for len(out) < n {
		match, ok := s.nextWall(wall, limit)
		if !ok {
			return nil, fmt.Errorf("%q has no occurrence within %d years", s.expr, maxYearsAhead)
		}
		if t := instant(match, loc); t.After(prev) {
			out = append(out, t)
			prev = t
		}
		wall = match.Add(time.Minute)
	}
	return out, nil
}

// nextWall finds the first wall-clock minute at or after w that the fields
// admit, skipping a whole month, day or hour at a time rather than a minute.
func (s *Schedule) nextWall(w time.Time, limitYear int) (time.Time, bool) {
	for w.Year() <= limitYear {
		switch {
		case !s.month.has(int(w.Month())):
			w = time.Date(w.Year(), w.Month(), 1, 0, 0, 0, 0, time.UTC).AddDate(0, 1, 0)
		case !s.dayMatch(w):
			w = time.Date(w.Year(), w.Month(), w.Day(), 0, 0, 0, 0, time.UTC).AddDate(0, 0, 1)
		case !s.hour.has(w.Hour()):
			w = time.Date(w.Year(), w.Month(), w.Day(), w.Hour(), 0, 0, 0, time.UTC).Add(time.Hour)
		case !s.minute.has(w.Minute()):
			w = w.Add(time.Minute)
		default:
			return w, true
		}
	}
	return time.Time{}, false
}

// dayMatch applies the day-of-month / day-of-week rule: when both fields are
// restricted a day qualifies if either matches, otherwise both must.
func (s *Schedule) dayMatch(t time.Time) bool {
	dom, dow := s.dom.has(t.Day()), s.dow.has(int(t.Weekday()))
	if s.dom.restricted && s.dow.restricted {
		return dom || dow
	}
	return dom && dow
}

// Match reports whether the schedule fires at exactly t, in t's own location.
func (s *Schedule) Match(t time.Time) bool {
	if t.Second() != 0 || t.Nanosecond() != 0 {
		return false
	}
	return s.month.has(int(t.Month())) && s.dayMatch(t) && s.hour.has(t.Hour()) && s.minute.has(t.Minute())
}

// instant places a wall-clock slot on the real timeline in loc. If that slot
// was skipped by a daylight-saving jump it does not exist, and the occurrence
// moves to the moment of the jump — the first wall-clock time after it that
// does exist.
func instant(wall time.Time, loc *time.Location) time.Time {
	t := time.Date(wall.Year(), wall.Month(), wall.Day(), wall.Hour(), wall.Minute(), 0, 0, loc)
	if t.Year() == wall.Year() && t.Month() == wall.Month() && t.Day() == wall.Day() &&
		t.Hour() == wall.Hour() && t.Minute() == wall.Minute() {
		return t
	}
	return jump(t.Add(-24*time.Hour), t.Add(24*time.Hour), t)
}

// jump binary-searches (lo, hi] for the instant the zone offset changes.
func jump(lo, hi, fallback time.Time) time.Time {
	_, before := lo.Zone()
	if _, after := hi.Zone(); after == before {
		return fallback // no transition in range; nothing better to offer
	}
	for hi.Sub(lo) > time.Second {
		mid := lo.Add(hi.Sub(lo) / 2)
		if _, o := mid.Zone(); o == before {
			lo = mid
		} else {
			hi = mid
		}
	}
	return hi
}
