package main

import (
	"fmt"
	"strconv"
	"strings"
)

var fullMonths = []string{"January", "February", "March", "April", "May", "June",
	"July", "August", "September", "October", "November", "December"}

var fullDays = []string{"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"}

// Describe renders the schedule as one plain-English line.
func (s *Schedule) Describe() string {
	parts := []string{}

	when, fixedTime := s.timePhrase()
	parts = append(parts, when)

	var days []string
	if s.dom.restricted {
		days = append(days, "on "+plural("day", "days", s.dom)+" "+list(s.dom, strconv.Itoa)+" of the month")
	}
	if s.dow.restricted {
		days = append(days, "on "+list(s.dow, func(v int) string { return fullDays[v] }))
	}
	switch {
	case len(days) > 0:
		// Both restricted means either may match, which "or" says exactly.
		parts = append(parts, strings.Join(days, " or "))
	case fixedTime:
		parts = append(parts, "every day")
	}

	if s.month.restricted {
		parts = append(parts, "in "+list(s.month, func(v int) string { return fullMonths[v-1] }))
	}
	return strings.Join(parts, ", ")
}

// timePhrase describes the minute and hour fields, and reports whether the
// result names a single clock time (which alone reads well with "every day").
func (s *Schedule) timePhrase() (string, bool) {
	mins, hours := values(s.minute), values(s.hour)
	switch {
	case !s.minute.restricted && !s.hour.restricted:
		return "every minute", false
	case !s.hour.restricted:
		if n, ok := evenStep(mins, 59); ok {
			return fmt.Sprintf("every %d minutes", n), false
		}
		return "at " + plural("minute", "minutes", s.minute) + " " + list(s.minute, strconv.Itoa) + " of every hour", false
	case len(mins) == 1 && len(hours) == 1:
		return fmt.Sprintf("at %02d:%02d", hours[0], mins[0]), true
	default:
		return "at " + plural("minute", "minutes", s.minute) + " " + list(s.minute, strconv.Itoa) +
			" past " + plural("hour", "hours", s.hour) + " " + list(s.hour, strconv.Itoa), false
	}
}

// evenStep reports the stride of a field written as */n — values evenly spaced
// from zero that run to the end of the field.
func evenStep(vals []int, max int) (int, bool) {
	if len(vals) < 2 || vals[0] != 0 {
		return 0, false
	}
	step := vals[1]
	for i, v := range vals {
		if v != i*step {
			return 0, false
		}
	}
	if vals[len(vals)-1]+step <= max {
		return 0, false
	}
	return step, true
}

func values(f field) []int {
	var out []int
	for v := 0; v < 64; v++ {
		if f.has(v) {
			out = append(out, v)
		}
	}
	return out
}

func plural(one, many string, f field) string {
	if len(values(f)) == 1 {
		return one
	}
	return many
}

// list renders a field's values, collapsing runs of three or more into
// "a through b", and joining the rest as "a, b and c".
func list(f field, name func(int) string) string {
	vals := values(f)
	var items []string
	for i := 0; i < len(vals); {
		j := i
		for j+1 < len(vals) && vals[j+1] == vals[j]+1 {
			j++
		}
		if j-i >= 2 {
			items = append(items, name(vals[i])+" through "+name(vals[j]))
			i = j + 1
			continue
		}
		items = append(items, name(vals[i]))
		i++
	}
	if len(items) == 1 {
		return items[0]
	}
	return strings.Join(items[:len(items)-1], ", ") + " and " + items[len(items)-1]
}
