package main

import (
	"flag"
	"fmt"
	"io"
	"time"
)

const usage = `usage: cron <command> [arguments]

  cron next <expr> --count N [--from <ISO8601>] [--tz <zone>]   the next N run times
  cron describe <expr>                                          one plain-English line
  cron match <expr> <ISO8601>                                   exit 0 if it would run

An expression is five fields — minute hour day-of-month month day-of-week — or one
of the macros @hourly @daily @weekly @monthly @yearly.
`

// Exit codes: 0 success, 1 no match or no occurrence, 2 bad usage or a bad expression.
func run(args []string, stdout, stderr io.Writer) int {
	if len(args) == 0 {
		fmt.Fprint(stderr, usage)
		return 2
	}
	cmd, rest := args[0], args[1:]
	switch cmd {
	case "next":
		return next(rest, stdout, stderr)
	case "describe":
		return describe(rest, stdout, stderr)
	case "match":
		return match(rest, stderr)
	case "help", "-h", "--help":
		fmt.Fprint(stdout, usage)
		return 0
	default:
		fmt.Fprintf(stderr, "cron: unknown command %q\n\n%s", cmd, usage)
		return 2
	}
}

func next(args []string, stdout, stderr io.Writer) int {
	if len(args) == 0 {
		fmt.Fprint(stderr, usage)
		return 2
	}
	fs := flag.NewFlagSet("next", flag.ContinueOnError)
	fs.SetOutput(stderr)
	count := fs.Int("count", 1, "how many run times to print")
	from := fs.String("from", "", "ISO 8601 time to start from (default: now)")
	tz := fs.String("tz", "UTC", "IANA time zone the times are computed in")
	if err := fs.Parse(args[1:]); err != nil {
		return 2
	}
	if *count < 1 {
		fmt.Fprintf(stderr, "cron: --count must be at least 1, got %d\n", *count)
		return 2
	}

	loc, err := time.LoadLocation(*tz)
	if err != nil {
		fmt.Fprintf(stderr, "cron: unknown time zone %q\n", *tz)
		return 2
	}
	start := time.Now().In(loc)
	if *from != "" {
		start, err = parseTime(*from, loc)
		if err != nil {
			fmt.Fprintf(stderr, "cron: --from: %v\n", err)
			return 2
		}
		start = start.In(loc)
	}

	s, err := Parse(args[0])
	if err != nil {
		fmt.Fprintf(stderr, "cron: %v\n", err)
		return 2
	}
	times, err := s.NextN(start, *count)
	if err != nil {
		fmt.Fprintf(stderr, "cron: %v\n", err)
		return 1
	}
	for _, t := range times {
		fmt.Fprintln(stdout, t.Format(time.RFC3339))
	}
	return 0
}

func describe(args []string, stdout, stderr io.Writer) int {
	if len(args) != 1 {
		fmt.Fprint(stderr, usage)
		return 2
	}
	s, err := Parse(args[0])
	if err != nil {
		fmt.Fprintf(stderr, "cron: %v\n", err)
		return 2
	}
	fmt.Fprintln(stdout, s.Describe())
	return 0
}

func match(args []string, stderr io.Writer) int {
	if len(args) != 2 {
		fmt.Fprint(stderr, usage)
		return 2
	}
	s, err := Parse(args[0])
	if err != nil {
		fmt.Fprintf(stderr, "cron: %v\n", err)
		return 2
	}
	// Parsed in the timestamp's own offset when it carries one, UTC otherwise.
	t, err := parseTime(args[1], time.UTC)
	if err != nil {
		fmt.Fprintf(stderr, "cron: %v\n", err)
		return 2
	}
	if !s.Match(t) {
		return 1
	}
	return 0
}

// parseTime accepts ISO 8601 with or without an offset; without one, the time
// is read in loc.
func parseTime(text string, loc *time.Location) (time.Time, error) {
	for _, layout := range []string{time.RFC3339, "2006-01-02T15:04:05", "2006-01-02T15:04", "2006-01-02"} {
		if t, err := time.ParseInLocation(layout, text, loc); err == nil {
			return t, nil
		}
	}
	return time.Time{}, fmt.Errorf("%q is not an ISO 8601 time", text)
}
